const weddingTasks=[['budget','Bajet','Tetapkan bajet keseluruhan majlis'],['guestlist','Tetamu','Sediakan senarai jemputan'],['venue','Vendor','Tempah dewan atau lokasi majlis'],['catering','Vendor','Pilih pakej katering'],['photo','Vendor','Tempah jurugambar dan videografer'],['course','Dokumen','Semak keperluan kursus kahwin'],['documents','Dokumen','Lengkapkan dokumen dan urusan nikah'],['outfit','Persiapan','Pilih busana dan tetapkan tarikh fitting'],['makeup','Vendor','Tempah jurusolek'],['pelamin','Vendor','Pilih dekorasi dan pelamin'],['cards','Tetamu','Sediakan kad atau jemputan digital'],['rings','Persiapan','Sediakan cincin dan hantaran'],['timeline','Hari majlis','Susun atur cara dan tugasan keluarga'],['qr','Hari majlis','Cetak QR kenangan untuk meja tetamu'],['confirm','Hari majlis','Sahkan semua vendor dan waktu ketibaan'],['essentials','Hari majlis','Sediakan dokumen, barang penting dan kit kecemasan']];
let checklistFilter='all';function tasks(){return event.checklist||weddingTasks.map(([id,category,title])=>({id,category,title,done:false,due:''}))}function checklistProgress(){let t=tasks(),done=t.filter(x=>x.done).length;return {total:t.length,done,percent:t.length?Math.round(done/t.length*100):0}}function checklistSummary(){if(!event)return '';const p=checklistProgress(),todo=tasks().filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4);return '<section class="panel dashboard-checklist"><div class="sectionrow" style="margin:0 0 18px"><div><span class="eyebrow">SEDIKIT DEMI SEDIKIT, MENUJU HARI BAHAGIA</span><h3 style="margin-top:9px">Checklist persiapan majlis</h3></div><button class="btn small" onclick="navigate(\'checklist\')">Lihat semua ↗</button></div><div class="check-progress"><div><strong>'+p.percent+'%</strong><span>'+p.done+' daripada '+p.total+' tugasan selesai</span></div><div class="progress-track"><span style="width:'+p.percent+'%"></span></div></div><div class="summary-tasks">'+(todo.length?todo.map(t=>taskRow(t,true)).join(''):'<p class="formhelp">Semua tugasan selesai. Kini masa untuk meraikan cinta ♡</p>')+'</div><p class="formhelp" style="margin:16px 0 0">Checklist untuk '+esc(event.name)+'. Anda boleh ubah senarai mengikut keperluan majlis.</p></section>'}
function taskRow(t,compact=false){const overdue=t.due&&!t.done&&t.due<new Date().toLocaleDateString('en-CA');return '<div class="taskrow '+(t.done?'done':'')+'"><label class="task-main"><input type="checkbox" '+(t.done?'checked':'')+' onchange="toggleTask(\''+t.id+'\',this.checked)" '+(checklistBusy?'disabled':'')+'><span><strong>'+esc(t.title)+'</strong><small>'+esc(t.category)+(t.due?' · <span class="'+(overdue?'overdue':'')+'">'+date(t.due)+'</span>':'')+'</small></span></label>'+(compact?'':'<div class="task-tools"><input type="date" aria-label="Tarikh sasaran '+esc(t.title)+'" value="'+(t.due||'')+'" onchange="dateTask(\''+t.id+'\',this.value)" '+(checklistBusy?'disabled':'')+'><button type="button" title="Padam tugasan" aria-label="Padam '+esc(t.title)+'" onclick="deleteTask(\''+t.id+'\')" '+(checklistBusy?'disabled':'')+'>×</button></div>')+'</div>'}
function checklistPage(){let list=tasks().filter(t=>checklistFilter==='all'||checklistFilter==='done'&&t.done||checklistFilter==='todo'&&!t.done),p=checklistProgress();shell(title('Langkah kecil menuju hari bahagia.','Rancang bersama, tanda satu per satu. Checklist disimpan untuk majlis anda.','<select style="width:auto;max-width:210px" onchange="selectEvent(this.value,\'checklist\')">'+events.map(e=>'<option value="'+e.id+'" '+(e.id===event.id?'selected':'')+'>'+esc(e.name)+'</option>').join('')+'</select>')+'<div class="panel checklist-hero"><div><span class="eyebrow">'+esc(event.name)+'</span><h2 style="margin-top:12px">'+p.done+' / '+p.total+' tugasan selesai</h2><p class="formhelp">Tak perlu sempurna sekaligus. Setiap tanda ✓ membawa anda selangkah lebih dekat.</p></div><div class="progress-ring" style="--progress:'+p.percent+'%"><span>'+p.percent+'<small>%</small></span></div><div class="progress-track full"><span style="width:'+p.percent+'%"></span></div></div><div class="panel" style="margin-top:22px"><h3>Tambah tugasan anda</h3><form id="taskform" class="taskform"><input class="field" id="tasktitle" placeholder="Contoh: Ambil baju nikah" required maxlength="160"><select id="taskcategory" aria-label="Kategori">'+['Persiapan','Bajet','Vendor','Tetamu','Dokumen','Hari majlis'].map(x=>'<option>'+x+'</option>').join('')+'</select><input class="field" type="date" id="taskdue" aria-label="Tarikh sasaran"><button class="btn primary" type="submit" '+(checklistBusy?'disabled':'')+'>＋ Tambah</button></form></div><div class="tabs" role="group" aria-label="Tapis checklist">'+[['all','Semua tugasan'],['todo','Belum selesai'],['done','Sudah selesai']].map(([k,t])=>'<button class="'+(checklistFilter===k?'active':'')+'" onclick="checklistFilter=\''+k+'\';checklistPage()">'+t+'</button>').join('')+'</div><div class="panel checklist-list">'+(list.length?list.map(t=>taskRow(t)).join(''):'<div class="empty"><h3>'+(p.total?'Semua beres di sini ♡':'Senarai anda masih kosong.')+'</h3><p>Tambah tugasan baharu atau pilih penapis lain.</p></div>')+'</div><p class="formhelp">Senarai cadangan ini panduan umum. Semak urusan nikah dan keperluan dokumen dengan pihak berkuasa berkaitan di tempat anda.</p>');$('#taskform').onsubmit=async e=>{e.preventDefault();let title=$('#tasktitle').value.trim();if(!title)return;const t=[...tasks(),{id:crypto.randomUUID(),title,category:$('#taskcategory').value,due:$('#taskdue').value,done:false}];await saveTasks(t)}}
let checklistBusy=false;async function saveTasks(list){if(checklistBusy)return;if(list.length>100){toast('Maksimum 100 tugasan setiap majlis.');return}checklistBusy=true;try{const d=await api('/api/events/'+event.id,{method:'PATCH',body:JSON.stringify({checklist:list})});event={...event,...d};events=events.map(x=>x.id===event.id?{...x,checklist:d.checklist}:x);toast('Checklist dikemas kini ♡')}catch(e){toast(e.message)}finally{checklistBusy=false;renderOwner()}}function toggleTask(id,done){saveTasks(tasks().map(t=>t.id===id?{...t,done}:t))}function dateTask(id,due){saveTasks(tasks().map(t=>t.id===id?{...t,due}:t))}function deleteTask(id){saveTasks(tasks().filter(t=>t.id!==id))}

const inviteLink=e=>location.origin+(ownerDemo?'/invitation-demo?template='+(e.invitation?.template||'garden'):'/i/'+e.id);let rsvpAnswers=[],rsvpFilter='all';const inviteDefaults=e=>({title:'Walimatulurus',hosts:'',template:'garden',message:'Dengan penuh kesyukuran, kami menjemput anda dan keluarga untuk meraikan hari bahagia kami. Kehadiran dan doa restu anda amat kami hargai.',address:'',deadline:'',open:true,...(e.invitation||{})});
