function invitationOwner(){invitationDirty=false;if(!hasPremium(event)){shell(title('E-Kad & RSVP.','E-Kad dan RSVP belum termasuk dalam pakej anda. Tekan Locked untuk lihat pakej.')+'<section class="panel premium-lock"><div class="lock-badge">✉</div><div><span class="eyebrow">E-KAD + RSVP · LOCKED</span><h2 style="margin-top:12px">Jemput. Sahkan. Raikan.</h2><p>Kad jemputan digital mengikut tema majlis, pengesahan kehadiran tanpa login, kiraan dewasa dan kanak-kanak serta pautan lokasi dan kalendar. Eksport CSV tersedia dalam Max.</p><a class="btn" href="/#pakej" target="_blank" rel="noopener">Lihat contoh e-kad ↗</a> '+lockedFeatureButton('invitation')+'<p class="formhelp">Tekan Locked untuk lihat pilihan pakej yang membuka E-Kad dan RSVP.</p></div></section>');return}const i=inviteDefaults(event);shell(title('Jemput mereka ke hari bahagia.','Satu editor untuk E-Kad, poster IG, butiran majlis dan RSVP.', '<select style="width:auto;max-width:210px" onchange="selectEvent(this.value,\'invitation\')">'+events.map(e=>'<option value="'+e.id+'" '+(e.id===event.id?'selected':'')+'>'+esc(e.name)+'</option>').join('')+'</select>')+'<div class="banner"><div><strong>E-Kad yang disimpan</strong><p>'+inviteLink(event)+'</p></div><div style="display:flex;gap:7px"><button class="btn small" onclick="openIGPoster(false)">Poster IG daripada E-Kad ↓</button><button class="btn small" onclick="copyInvitation()">Salin pautan</button><a class="btn small" href="'+inviteLink(event)+'" target="_blank" rel="noopener">Preview ↗</a></div></div><form id="inviteform" class="panel"><div id="invitetemplates">'+invitationTemplateCards()+'</div><section class="invitation-event-details"><span class="eyebrow">BUTIRAN MAJLIS</span><h3 style="margin-top:12px">Maklumat untuk E-Kad & poster IG</h3><p class="formhelp">Butiran yang disimpan di sini turut digunakan pada Galeri Tetamu.</p><div class="formgrid" style="margin-top:18px"><div class="full"><label class="fieldlabel" for="iname">Nama pasangan</label><input class="field" id="iname" required maxlength="80" value="'+esc(event.name)+'"></div><div><label class="fieldlabel" for="idate">Tarikh majlis</label><input class="field" type="date" id="idate" required value="'+esc(event.date)+'"></div><div><label class="fieldlabel" for="itime">Masa majlis</label><input class="field" id="itime" maxlength="80" value="'+esc(event.eventTime||'')+'"></div><div class="full"><label class="fieldlabel" for="ivenue">Lokasi majlis</label><input class="field" id="ivenue" maxlength="120" value="'+esc(event.venue)+'"></div></div></section><span class="eyebrow">KATA-KATA JEMPUTAN</span><h3 style="margin-top:12px">Sentuhan daripada keluarga anda</h3><div class="formgrid" style="margin-top:21px"><div><label class="fieldlabel" for="ititle">Tajuk kad</label><input class="field" id="ititle" maxlength="100" value="'+esc(i.title)+'"></div><div><label class="fieldlabel" for="ihosts">Nama tuan rumah / ibu bapa (pilihan)</label><input class="field" id="ihosts" maxlength="180" value="'+esc(i.hosts)+'"></div><div class="full"><label class="fieldlabel" for="imessage">Teks jemputan</label><textarea id="imessage" maxlength="700">'+esc(i.message)+'</textarea></div><div class="full"><label class="fieldlabel" for="iaddress">Alamat penuh untuk lokasi</label><textarea id="iaddress" style="min-height:80px" maxlength="300" placeholder="Alamat digunakan pada pautan Google Maps dan Waze">'+esc(i.address)+'</textarea></div><div><label class="fieldlabel" for="ideadline">Tarikh akhir RSVP (pilihan)</label><input class="field" id="ideadline" type="date" value="'+esc(i.deadline)+'"></div><div><p class="formhelp">Simpan perubahan sebelum berkongsi pautan atau menjana poster. Simpan tarikh menambah acara sepanjang hari pada kalendar tetamu.</p></div></div><label class="switchrow"><div><strong>Buka RSVP</strong><p>Tetamu boleh hantar atau kemas kini jawapan sehingga tarikh akhir.</p></div><input type="checkbox" id="iopen" '+(i.open?'checked':'')+'></label><div class="error" id="inviteerror" role="alert"></div><button class="btn primary" type="submit" style="margin-top:20px">Jana E-Kad ↗</button></form><section class="panel" style="margin-top:23px"><div class="sectionrow" style="margin-top:0"><h3>Jawapan RSVP</h3><div><button class="btn small" onclick="loadRSVP()">↻ Kemas kini</button> '+(hasFeature(event,'csv')?'<button class="btn small" onclick="exportRSVP()">Eksport CSV ↓</button>':'<span class="locked-feature-inline"><span>Eksport CSV</span>'+lockedFeatureButton('csv')+'</span>')+'</div></div><div id="rsvpresults"><p class="formhelp">Memuatkan jawapan…</p></div></section>');$('#inviteform').onsubmit=async e=>{e.preventDefault();if(!$('#itemplate').value){$('#inviteerror').textContent='Pilih satu imej E-Kad dahulu.';return}if(!$('#iname').value.trim()||!$('#idate').value){$('#inviteerror').textContent='Isi nama pasangan dan tarikh majlis.';return}e.submitter.disabled=true;try{let d=await api('/api/events/'+event.id,{method:'PATCH',body:JSON.stringify({name:$('#iname').value.trim(),date:$('#idate').value,eventTime:$('#itime').value,venue:$('#ivenue').value,invitation:{template:$('#itemplate').value,title:$('#ititle').value,hosts:$('#ihosts').value,message:$('#imessage').value,address:$('#iaddress').value,deadline:$('#ideadline').value,open:$('#iopen').checked}})});event={...event,...d};events=events.map(x=>x.id===event.id?{...x,...d}:x);toast('E-Kad dan butiran majlis disimpan ♡');invitationOwner();showGeneratedInvitation()}catch(err){$('#inviteerror').textContent=err.message}finally{e.submitter.disabled=false}};$('#inviteform').oninput=updateInvitationDraftPreview;loadRSVP()}
async function copyInvitation(){try{await navigator.clipboard.writeText(inviteLink(event));toast('Pautan e-kad disalin.')}catch{open('<h3>Pautan jemputan anda</h3><input class="field" readonly value="'+inviteLink(event)+'" onclick="this.select()">')}}
async function loadRSVP(){const id=event.id;try{let answers=await api('/api/events/'+id+'/rsvps');if(event.id!==id||active!=='invitation')return;rsvpAnswers=answers;renderRSVP()}catch(e){if($('#rsvpresults'))$('#rsvpresults').textContent=e.message}}
function renderRSVP(){let yes=rsvpAnswers.filter(a=>a.status==='yes'),adults=yes.reduce((n,a)=>n+a.adults,0),children=yes.reduce((n,a)=>n+a.children,0),filtered=rsvpAnswers.filter(a=>rsvpFilter==='all'||a.status===rsvpFilter);$('#rsvpresults').innerHTML='<div class="metrics">'+[[adults+children,'Jumlah hadir'],[adults,'Dewasa'],[children,'Kanak-kanak'],[rsvpAnswers.length,'Jawapan diterima']].map(([n,l])=>'<div class="metric"><span>'+l+'</span><strong>'+n+'</strong></div>').join('')+'</div><div class="tabs">'+[['all','Semua'],['yes','Hadir'],['no','Tidak hadir'],['maybe','Belum pasti']].map(([k,l])=>'<button class="'+(rsvpFilter===k?'active':'')+'" onclick="rsvpFilter=\''+k+'\';renderRSVP()">'+l+'</button>').join('')+'</div>'+(filtered.length?'<div class="rsvp-table-wrap"><table class="rsvp-table"><thead><tr><th>Nama</th><th>Jawapan</th><th>Dewasa</th><th>Kanak-kanak</th><th>Nota</th></tr></thead><tbody>'+filtered.map(a=>'<tr><td>'+esc(a.name)+'</td><td><span class="pill">'+({yes:'Hadir',no:'Tidak hadir',maybe:'Belum pasti'}[a.status])+'</span></td><td>'+a.adults+'</td><td>'+a.children+'</td><td>'+esc(a.note)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty"><h3>Menanti khabar daripada mereka.</h3><p>Kongsi pautan e-kad untuk mula menerima jawapan.</p></div>')+'<p class="formhelp">Jawapan RSVP hanya untuk bakal pengantin. Hantaran semula daripada sesi peranti yang sama mengemas kini jawapan terdahulu. Bilangan ini berdasarkan pengakuan tetamu.</p>'}
async function exportRSVP(){if(!hasFeature(event,'csv')){await openLockedFeature('csv');return}try{const exportRows=await api('/api/events/'+event.id+'/rsvps/export');const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Nama','Status','Dewasa','Kanak-kanak','Nota','Dikemas kini'],...exportRows.map(a=>[a.name,{yes:'Hadir',no:'Tidak hadir',maybe:'Belum pasti'}[a.status],a.adults,a.children,a.note,a.updated])];saveFile(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'sejenak-rsvp.csv')}catch(err){toast(err.message)}}
const invitationDemo=location.pathname==='/invitation-demo';function invitationCard(){theme();const d=ecardDesign(event),i=inviteDefaults(event),address=i.address||event.venue,closed=i.open===false||i.deadline&&new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kuala_Lumpur'})>i.deadline;root.innerHTML=(invitationDemo?'<div class="demo-strip">Contoh E-Kad · Jawapan tidak dihantar kepada pengantin · <a href="/#pakej">Cuba editor E-Kad ↗</a></div>':'')+'<header class="guestheader">'+brand+'<a href="/" class="eyebrow">E-JEMPUTAN</a></header><main class="invitation-page">'+weddingCountdownHTML()+'<article class="digital-card invite-template-'+(findInvitationTemplate(i.template)?i.template:'garden')+'" style="'+ecardStyle(i.template)+'"><img class="ecard-template-art" src="'+invitationArtwork(i.template)+'" alt="" aria-hidden="true">'+'<div class="invite-floral" style="color:'+d.accentColor+'">✧ <span>✿</span> ✧</div>'+'<div class="digital-card-copy">'+bismillahHTML('invitation-bismillah')+'<div class="eyebrow" style="color:'+d.accentColor+'">'+esc(i.title||'Walimatulurus')+'</div>'+(i.hosts?'<p class="invite-hosts">'+esc(i.hosts)+'</p>':'')+'<h1 style="'+fontStyle(d.font)+';color:'+d.primaryColor+'">'+esc(event.name)+'</h1><div class="floral-line" style="color:'+d.accentColor+'">— ✿ —</div><p class="invite-message">'+esc(i.message)+'</p><div class="invite-details"><span class="eyebrow">TARIKH MAJLIS</span><time class="invite-date" datetime="'+esc(event.date)+'">'+date(event.date)+'</time>'+(event.eventTime?'<p>'+esc(event.eventTime)+'</p>':'')+'<h3>'+esc(event.venue)+'</h3>'+(i.address?'<p>'+esc(i.address)+'</p>':'')+'</div><a class="btn primary" style="width:100%;margin-top:21px" href="#rsvp-form">'+(closed?'RSVP ditutup':'Sahkan kehadiran ♡')+'</a><p class="formhelp">'+(i.deadline?'Mohon jawapan sebelum '+date(i.deadline)+'.':'Kehadiran anda amat bermakna buat kami.')+'</p></div></article>'+'<section class="panel invitation-rsvp" id="rsvp-form"><span class="eyebrow">KHABARKAN KEHADIRAN ANDA</span><h2 style="margin-top:15px">Jumpa anda di sana?</h2><p id="rsvpremembered" class="formhelp" role="status"></p>'+(closed?'<p class="muted">Tempoh RSVP telah ditutup. Sila hubungi tuan rumah untuk pertanyaan.</p>':'<form id="rsvpform"><label class="fieldlabel" for="rname">Nama anda / wakil keluarga</label><input class="field" id="rname" required maxlength="80" autocomplete="name"><label class="fieldlabel" for="rstatus" style="margin-top:17px">Adakah anda akan hadir?</label><select id="rstatus" onchange="attendanceFields()"><option value="yes">Ya, saya akan hadir</option><option value="no">Maaf, tidak dapat hadir</option><option value="maybe">Belum pasti</option></select><div class="formgrid" id="attendancecounts" style="margin-top:17px"><div><label class="fieldlabel" for="radults">Dewasa (termasuk anda)</label><input class="field" type="number" min="1" max="10" value="1" id="radults" required></div><div><label class="fieldlabel" for="rchildren">Kanak-kanak</label><input class="field" type="number" min="0" max="10" value="0" id="rchildren" required></div></div><label class="rsvp-remember-option"><input type="checkbox" id="rremember" checked> Ingat nama dan jawapan pada peranti ini</label><button type="button" class="btn small" id="forgetrsvp" hidden onclick="forgetGuestRSVP()">Padam maklumat pada peranti ini</button><div class="error" id="rsvperror" role="alert"></div><button class="btn primary" type="submit" style="width:100%">Hantar jawapan ♡</button><p id="rsvpreceipt" class="formhelp" role="status"></p><div id="rsvpposter" class="poster-rsvp-action" hidden><button type="button" class="btn primary" onclick="guestRSVPPoster()">Jana poster jemputan IG · 9:16 ↓</button><p class="formhelp">Poster menggunakan nama anda daripada RSVP, bersama jemputan untuk keluarga.</p></div></form>')+'</section>'+(!invitationDemo?'<a class="btn" href="/e/'+event.id+'" style="margin:25px auto;display:flex;width:max-content">Lihat galeri kenangan ↗</a>':'')+'<p class="invite-signoff">Dengan cinta, '+esc(event.name)+' ♡</p><footer class="invitation-footer"><span class="eyebrow">MAKLUMAT MAJLIS</span><div class="invite-actions">'+(address?'<a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address)+'">'+ico('pin')+'<span>Google Maps ↗</span></a><a class="btn" target="_blank" rel="noopener" href="https://waze.com/ul?q='+encodeURIComponent(address)+'&navigate=yes">'+ico('navigation')+'<span>Waze ↗</span></a>':'')+'<button class="btn" onclick="downloadCalendar()">'+ico('calendar')+'<span>Simpan tarikh ↓</span></button><button class="btn" onclick="guestQR()">'+ico('grid')+' QR jemputan</button><button class="btn" onclick="shareGuestURL()">'+ico('share')+'<span>Kongsi ↗</span></button></div><div class="invitation-powered"><span>Powered by</span>'+sejenakLogo('powered-logo')+'</div></footer></main>';startWeddingCountdown();if(!closed){$('#rsvpform').onsubmit=submitRSVP;$('#rsvpform').oninput=updateGuestPoster;restoreGuestRSVP();updateGuestPoster()}}
function attendanceFields(){const yes=$('#rstatus').value==='yes';$('#attendancecounts').hidden=!yes;$('#attendancecounts').style.display=yes?'grid':'none';$('#radults').disabled=!yes;$('#rchildren').disabled=!yes}

function rsvpProfileKey(){return 'sejenak-rsvp-profile-'+event.id}
function rememberGuestRSVP(details){guestName=details.name;if(!details.remember){preferences.remove(rsvpProfileKey());if($('#forgetrsvp'))$('#forgetrsvp').hidden=true;return}const profile={name:details.name,status:details.status,adults:details.status==='yes'?details.adults:0,children:details.status==='yes'?details.children:0,eventId:details.eventId};preferences.set(rsvpProfileKey(),JSON.stringify(profile));if($('#forgetrsvp'))$('#forgetrsvp').hidden=false}
function restoreGuestRSVP(){if(!$('#rname'))return;try{const raw=preferences.get(rsvpProfileKey()),p=raw?JSON.parse(raw):null;if(!p){$('#rname').value=guestName;return}if(p.eventId!==event.id||typeof p.name!=='string'||!p.name.trim()||p.name.length>80||!['yes','no','maybe'].includes(p.status)||!Number.isInteger(p.adults)||p.adults<0||p.adults>10||p.status==='yes'&&p.adults<1||!Number.isInteger(p.children)||p.children<0||p.children>10)return;$('#rname').value=p.name;$('#rstatus').value=p.status;$('#radults').value=Math.max(1,p.adults);$('#rchildren').value=p.children;confirmedGuestRSVP={name:p.name,status:p.status,eventId:event.id};attendanceFields();$('#rsvpremembered').textContent='Jawapan terakhir pada peranti ini telah diisi semula. Semak dan hantar untuk mengemas kini.';$('#forgetrsvp').hidden=false}catch{preferences.remove(rsvpProfileKey())}}
function forgetGuestRSVP(){guestName='';preferences.remove(rsvpProfileKey());confirmedGuestRSVP=null;$('#rname').value='';$('#rstatus').value='yes';$('#radults').value='1';$('#rchildren').value='0';if($('#rnote'))$('#rnote').value='';$('#rremember').checked=false;$('#forgetrsvp').hidden=true;$('#rsvpreceipt').textContent='';$('#rsvpremembered').textContent='Maklumat di peranti ini dipadam. Jawapan RSVP yang telah dihantar kepada bakal pengantin kekal.';attendanceFields();updateGuestPoster()}

let confirmedGuestRSVP=null;
function updateGuestPoster(){const area=$('#rsvpposter');if(!area)return;const name=$('#rname')?.value.trim(),status=$('#rstatus')?.value;area.hidden=!(confirmedGuestRSVP&&confirmedGuestRSVP.eventId===event.id&&confirmedGuestRSVP.name===name&&confirmedGuestRSVP.status==='yes'&&status==='yes'&&name)}
function guestRSVPPoster(){updateGuestPoster();if(!$('#rsvpposter')||$('#rsvpposter').hidden)return;openIGPoster(invitationDemo,confirmedGuestRSVP.name,true)}
async function submitRSVP(e){e.preventDefault();const details={name:$('#rname').value.trim(),status:$('#rstatus').value,eventId:event.id,adults:Number($('#radults')?.value||1),children:Number($('#rchildren')?.value||0),remember:$('#rremember')?.checked!==false};if(!details.name){$('#rsvperror').textContent='Sila isi nama anda.';return}confirmedGuestRSVP=null;updateGuestPoster();if(invitationDemo){confirmedGuestRSVP=details;rememberGuestRSVP(details);$('#rsvpreceipt').textContent='Terima kasih ♡ Ini contoh sahaja; jawapan tidak disimpan.';updateGuestPoster();return}let b=e.submitter;b.disabled=true;$('#rsvperror').textContent='';try{const storageKey='sejenak-rsvp-'+event.id;let token=preferences.get(storageKey);if(!token){token=crypto.randomUUID();preferences.set(storageKey,token)}await api('/api/rsvp/'+event.id,{method:'POST',body:JSON.stringify({token,name:details.name,status:details.status,adults:details.adults,children:details.children,note:''})});confirmedGuestRSVP=details;rememberGuestRSVP(details);$('#rsvpreceipt').textContent='Jawapan anda telah disimpan. Terima kasih atas khabar daripada anda ♡';updateGuestPoster();toast('RSVP diterima ♡')}catch(err){$('#rsvperror').textContent=err.message}finally{b.disabled=false}}

function downloadCalendar(){const start=event.date.replace(/-/g,''),endDate=new Date(event.date+'T12:00:00Z');endDate.setUTCDate(endDate.getUTCDate()+1);const end=endDate.toISOString().slice(0,10).replace(/-/g,''),ics=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sejenak//Wedding Invitation//MS','BEGIN:VEVENT','UID:'+event.id+'@sejenak','DTSTAMP:'+stamp,'DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+ics('Majlis '+event.name),'LOCATION:'+ics(inviteDefaults(event).address||event.venue),'DESCRIPTION:'+ics((event.eventTime?event.eventTime+'\n':'')+'Jemputan: '+(invitationDemo?location.href:inviteLink(event))),'END:VEVENT','END:VCALENDAR'];saveFile(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),'jemputan-majlis.ics')}

function currentGuestURL(){if(isDemo)return location.origin+'/demo';if(invitationDemo)return location.origin+'/invitation-demo';return location.origin+(location.pathname.startsWith('/i/')?'/i/':'/e/')+event.id}
function guestQR(){const url=currentGuestURL();open('<span class="eyebrow">KONGSI HARI BAHAGIA INI</span><h2 style="margin-top:14px">Scan, kongsi & cipta kenangan.</h2><div class="guest-qr-panel"><div id="publicqr"></div><h3>'+esc(event.name)+'</h3><p class="formhelp">'+(location.pathname.startsWith('/i/')||invitationDemo?'Scan untuk buka e-kad dan RSVP.':'Scan untuk buka galeri, kongsi foto dan ucapan.')+'<br>Tetamu tidak perlu log masuk.</p></div><div class="copyrow"><input class="field" id="publicguestlink" readonly aria-label="Pautan tetamu" value="'+esc(url)+'"><button class="btn" onclick="copyGuestURL()">Salin</button></div><div class="guest-qr-buttons"><button class="btn primary" onclick="shareGuestURL()">Kongsi pautan ↗</button><button class="btn" onclick="downloadGuestQR()">Muat turun QR ↓</button></div><p class="formhelp">'+(isDemo||invitationDemo?'QR demo ini membuka halaman contoh. Cipta Galeri Tetamu untuk dapat QR sendiri.':'Sesiapa dengan pautan ini boleh membukanya. Kongsi dengan tetamu majlis anda.')+'</p>');const qr=qrcode(0,'M');qr.addData(url);qr.make();$('#publicqr').innerHTML=qr.createSvgTag({cellSize:7,margin:4,scalable:true})}
async function copyGuestURL(){try{await navigator.clipboard.writeText(currentGuestURL());toast('Pautan tetamu disalin.')}catch{if(!$('#publicguestlink'))guestQR();$('#publicguestlink').focus();$('#publicguestlink').select();toast('Pilih dan salin pautan di atas.')}}
async function shareGuestURL(){if(navigator.share){try{await navigator.share({title:event.name,text:'Raikan hari bahagia bersama '+event.name,url:currentGuestURL()});return}catch(err){if(err.name==='AbortError')return}}await copyGuestURL()}
function downloadGuestQR(){saveFile(new Blob([$('#publicqr svg').outerHTML],{type:'image/svg+xml'}),'sejenak-qr-tetamu.svg')}


let weddingCountdownTimer;
function weddingCountdownHTML(){return '<section class="wedding-countdown" aria-label="Countdown ke hari majlis"><span class="eyebrow" id="countdowncaption">MENUJU HARI BAHAGIA</span><div class="countdown-units" role="timer" aria-label="Baki masa hingga tarikh majlis waktu Malaysia">'+[['days','Hari'],['hours','Jam'],['minutes','Minit'],['seconds','Saat']].map(([id,label])=>'<div class="countdown-unit"><strong id="countdown-'+id+'">00</strong><span>'+label+'</span></div>').join('')+'</div><p class="countdown-note">Hingga 12:00 tengah malam, '+date(event.date)+' · Waktu Malaysia</p></section>'}
function startWeddingCountdown(){clearInterval(weddingCountdownTimer);const targetDate=event.date;const tick=()=>{if(!$('#countdown-days')){clearInterval(weddingCountdownTimer);return}const p=countdownParts(targetDate);if(!p){clearInterval(weddingCountdownTimer);$('.wedding-countdown').hidden=true;return}for(const k of ['days','hours','minutes','seconds'])$('#countdown-'+k).textContent=String(p[k]).padStart(2,'0');if(p.arrived){$('#countdowncaption').textContent='HARI BAHAGIA TELAH TIBA ♡';clearInterval(weddingCountdownTimer)}};tick();if(!countdownParts(targetDate)?.arrived)weddingCountdownTimer=setInterval(tick,1000)}

function salamOwner(){if(!hasFeature(event,'salam')){shell(title('Sedikit tanda ingatan.','QR duit salam terus ke akaun bank atau e-wallet bakal pengantin.')+'<div class="panel premium-lock"><div class="lock-badge">♡</div><div><span class="eyebrow">DUIT SALAM · LOCKED</span><h2 style="margin-top:12px">Hadiah ikhlas daripada tetamu.</h2><p>Upload QR DuitNow daripada aplikasi bank atau e-wallet sendiri. Tetamu boleh simpan QR dan buat pindahan terus melalui aplikasi bank mereka.</p>'+lockedFeatureButton('salam')+'<p class="formhelp">Pembayaran pakej masih belum dibuka. Tiada QR bank contoh digunakan.</p></div></div>');return}shell(title('QR untuk duit salam.','Pindahan terus ke akaun anda. Platform tidak menerima atau mengesahkan bayaran.')+'<form id="salamform" class="panel"><span class="eyebrow">QR DUITNOW ANDA</span><h3 style="margin-top:13px">Tanda ingatan daripada mereka</h3><div class="formgrid" style="margin-top:22px"><div class="full"><label class="fieldlabel" for="srecipient">Nama penerima seperti dalam aplikasi bank</label><input class="field" id="srecipient" required maxlength="120" value="'+esc(event.paymentRecipient||'')+'" placeholder="Nama pemilik akaun penerima"></div><div class="full"><label class="fieldlabel" for="salamnote">Mesej kepada tetamu (pilihan)</label><textarea id="salamnote" maxlength="240" placeholder="Kehadiran dan doa anda sudah cukup bermakna buat kami.">'+esc(event.paymentNote||'')+'</textarea></div></div><label class="uploadzone">'+ico('gift')+' Upload gambar QR DuitNow<input type="file" id="salamfile" accept="image/jpeg,image/png,image/webp" '+(!event.paymentQrVersion?'required':'')+'><span class="formhelp">Ambil QR daripada aplikasi bank/e-wallet anda · JPG, PNG atau WebP sehingga 8 MB</span></label>'+(event.paymentQrVersion?'<div class="salam-owner-preview"><img src="/api/payment-qr/'+event.id+'?v='+event.paymentQrVersion+'" alt="QR DuitNow tersimpan"><button class="btn small" type="button" onclick="removeSalamQR()">Buang QR tersimpan</button></div>':'')+'<label class="switchrow"><div><strong>Paparkan kepada tetamu</strong><p>Butang Duit Salam muncul pada Galeri Tetamu apabila QR tersedia.</p></div><input id="salamenabled" type="checkbox" '+(event.paymentEnabled!==false?'checked':'')+'></label><div class="notice">Semak QR dan nama penerima dalam aplikasi bank sebelum dikongsi. Gunakan QR terima bayaran anda sendiri. Status pindahan dan resit tidak direkodkan oleh Sejenak.</div><div class="error" id="salamerror" role="alert"></div><button class="btn primary" type="submit" style="margin-top:20px">Simpan QR duit salam ↗</button></form>');$('#salamform').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;let textSaved=false;try{const f=$('#salamfile').files[0];if(f&&f.size>8*1024*1024)throw new Error('Had gambar QR ialah 8 MB.');const data=await api('/api/events/'+event.id,{method:'PATCH',body:JSON.stringify({paymentRecipient:$('#srecipient').value,paymentNote:$('#salamnote').value,paymentEnabled:$('#salamenabled').checked})});event={...event,...data};textSaved=true;if(f){const form=new FormData();form.set('qr',f);const d=await api('/api/events/'+event.id+'/payment-qr',{method:'POST',body:form});event.paymentQrVersion=d.paymentQrVersion}events=events.map(x=>x.id===event.id?{...x,...event,posts:undefined}:x);salamOwner();toast('QR duit salam disimpan ♡')}catch(err){$('#salamerror').textContent=(textSaved?'Maklumat disimpan. ':'')+err.message}finally{e.submitter.disabled=false}}}
function removeSalamQR(){open('<h2>Buang QR duit salam?</h2><p>Tetamu tidak lagi boleh membuka QR ini melalui app.</p><button class="btn primary" onclick="confirmRemoveSalamQR()">Ya, buang QR</button> <button class="btn" onclick="modal.close()">Batal</button>')}
async function confirmRemoveSalamQR(){try{await api('/api/events/'+event.id+'/payment-qr',{method:'DELETE'});delete event.paymentQrVersion;modal.close();salamOwner();toast('QR duit salam dibuang.')}catch(e){toast(e.message)}}
function salamAvailable(){return hasFeature(event,'salam')&&!!event.paymentQrVersion&&event.paymentEnabled!==false}
function guestSalamButton(){return salamAvailable()?'<button class="btn primary" onclick="openDuitSalam()">'+ico('gift')+' Duit salam</button>':''}
let posterBlob=null,posterObjectURL=null,posterBusy=false,posterRecipient='';
function posterRound(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
function posterText(ctx,text,y,{width=820,size=36,min=22,lines=2,height=120,font='DM Sans',italic=false,color='#542a35'}={}){let rows;for(let n=size;n>=min;n-=2){ctx.font=(italic?'italic ':'')+n+'px "'+font+'"';rows=wrapPosterText(t=>ctx.measureText(t).width,text,width);if(rows.length<=lines&&rows.length*n*1.2<=height){size=n;break}size=n}ctx.font=(italic?'italic ':'')+size+'px "'+font+'"';rows=posterTextBlock(t=>ctx.measureText(t).width,text,width,Math.min(lines,Math.max(1,Math.floor(height/(size*1.2)))));ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='top';for(let i=0;i<rows.length;i++)ctx.fillText(rows[i],540,y+i*size*1.2);return rows.length*size*1.2}
function posterImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('Gambar cover tidak dapat dimuatkan. Cuba semula.'));image.src=src})}
async function buildIGPoster(e,demo=false,recipient='Anda'){
 if(!hasFeature(e,'poster'))throw new Error('Poster IG belum termasuk dalam pakej ini.');
 const i=inviteDefaults(e),d=ecardDesign(e,i.template),artwork=invitationArtwork(i.template);
 if(document.fonts)await Promise.allSettled([document.fonts.load('40px "DM Sans"'),document.fonts.load('italic 80px "Cormorant Garamond"'),document.fonts.load('40px "Amiri"')]);
 const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const c=canvas.getContext('2d');if(!c)throw new Error('Pelayar ini tidak menyokong eksport poster.');
 c.fillStyle=d.backgroundColor;c.fillRect(0,0,1080,1920);
 const image=await posterImage(artwork);
 for(const part of invitationArtworkSlices(image.width,image.height))c.drawImage(image,0,part.sy,image.width,part.sh,0,part.dy,1080,part.dh);
 const ink=d.primaryColor,textFont=d.font==='modern'?'DM Sans':d.font==='classic'?'Georgia':'Cormorant Garamond';
 c.save();c.direction='rtl';posterText(c,bismillahText,210,{width:710,size:48,min:36,lines:1,height:62,font:'Amiri',color:ink});c.restore();
 posterText(c,i.title||'Walimatulurus',319,{width:710,size:25,min:21,lines:1,height:36,color:ink});
 if(i.hosts)posterText(c,i.hosts,370,{width:710,size:25,min:21,lines:2,height:64,color:ink});
 posterText(c,recipient,465,{width:710,size:34,min:24,lines:1,height:46,font:textFont,color:ink});
 posterText(c,'dan keluarga dijemput hadir ke majlis perkahwinan',520,{width:710,size:25,min:21,lines:2,height:62,color:ink});
 const name=e.name.includes('&')?e.name.split('&').map(x=>x.trim()).join('\n&\n'):e.name;
 posterText(c,name,635,{width:710,size:88,min:38,lines:3,height:270,font:textFont,italic:d.font!=='modern',color:ink});
 posterText(c,i.message,955,{width:690,size:29,min:23,lines:3,height:110,font:textFont,italic:true,color:ink});
 posterText(c,date(e.date),1120,{width:710,size:38,min:27,lines:1,height:52,color:ink});
 posterText(c,e.eventTime,1184,{width:710,size:28,min:22,lines:1,height:42,color:ink});
 posterText(c,e.venue||i.address,1255,{width:710,size:38,min:25,lines:2,height:100,font:textFont,color:ink});
 const qr=qrcode(0,'M');qr.addData(demo?location.origin+'/invitation-demo?template='+encodeURIComponent(i.template):inviteLink(e));qr.make();
 const qrimg=await posterImage(qr.createDataURL(5,4));c.fillStyle='#ffffff';posterRound(c,435,1460,210,210,14);c.fill();c.imageSmoothingEnabled=false;c.drawImage(qrimg,445,1470,190,190);c.imageSmoothingEnabled=true;
 posterText(c,demo?'CONTOH · SCAN E-KAD DEMO':'SCAN UNTUK E-KAD & RSVP',1690,{width:710,size:19,min:17,lines:1,height:28,color:ink});
 posterText(c,'Sejenak',1790,{width:710,size:28,min:24,lines:1,height:40,font:'Cormorant Garamond',italic:true,color:ink});
 return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Poster tidak dapat dieksport.')),'image/png'));
}
async function openIGPoster(demo=invitationDemo,recipient,fromRSVP=false){if(!demo&&!hasFeature(event,'poster')){await openLockedFeature('poster');return}if(!demo&&!fromRSVP&&active==='invitation'&&invitationDirty){open('<h2>Simpan E-Kad dahulu.</h2><p>Ada perubahan yang belum disimpan. Tekan Jana E-Kad dalam editor supaya poster IG menggunakan reka bentuk dan butiran terkini.</p><button class="btn primary" onclick="modal.close()">Kembali ke editor E-Kad</button>');return}if(!demo&&!fromRSVP&&!event.invitation?.template){open('<h2>Jana E-Kad dahulu.</h2><p>Pilih reka bentuk dan simpan E-Kad. Poster IG akan menggunakan artwork serta butiran yang sama.</p><button class="btn primary" onclick="modal.close();navigate(\'invitation\')">Buka E-Kad & RSVP ↗</button>');return}if(posterBusy)return;if(recipient===undefined){open('<span class="eyebrow">JEMPUTAN KHAS UNTUK MEREKA</span><h2 style="margin-top:14px">Siapa yang ingin dijemput?</h2><p>Nama ini dipaparkan pada poster. Anda boleh jana semula untuk tetamu lain.</p><form id="posterrecipientform"><label class="fieldlabel" for="posterrecipient">Nama penerima</label><input class="field" id="posterrecipient" required maxlength="80" placeholder="Contoh: Encik Ahmad" value="'+esc(posterRecipient)+'"><p class="formhelp">[Nama] dan keluarga dijemput hadir ke majlis perkahwinan '+esc(event.name)+'.</p><button class="btn primary" type="submit" style="width:100%;margin-top:16px">Jana poster IG 9:16 ↗</button></form>');$('#posterrecipientform').onsubmit=e=>{e.preventDefault();const name=$('#posterrecipient').value.trim();if(!name)return;posterRecipient=name;openIGPoster(demo,name)};return}posterRecipient=recipient;posterBusy=true;open('<span class="eyebrow">POSTER JEMPUTAN IG</span><h2 style="margin-top:13px">Sekeping jemputan untuk dikongsi.</h2><p>Menyediakan poster 1080 × 1920 daripada E-Kad yang disimpan…</p><div class="loading" style="padding:40px"><span class="spinner"></span></div>');try{posterBlob=await buildIGPoster(event,demo,recipient);if(posterObjectURL)URL.revokeObjectURL(posterObjectURL);posterObjectURL=URL.createObjectURL(posterBlob);open('<span class="eyebrow">SIAP UNTUK IG STORY · 9:16</span><h2 style="margin-top:13px">Poster E-Kad anda sudah tersedia.</h2><p class="formhelp">Reka bentuk: '+esc(findInvitationTemplate(inviteDefaults(event).template)?.name||'E-Kad anda')+'. Artwork, warna dan butiran mengikut E-Kad yang disimpan.</p><img class="ig-poster-preview" src="'+posterObjectURL+'" alt="Preview poster jemputan 9:16"><p class="formhelp" style="text-align:center">Jemputan untuk <strong>'+esc(recipient)+'</strong> dan keluarga</p><div class="poster-download-actions"><button class="btn primary" onclick="downloadIGPoster()">Muat turun PNG ↓</button><button class="btn" onclick="shareIGPoster()">Kongsi poster ↗</button>'+(!fromRSVP?'<button class="btn" onclick="openIGPoster('+demo+')">Tukar nama penerima</button>':'')+'</div><p class="formhelp">1080 × 1920 px · Tambah Link Sticker RSVP ketika pos di IG. QR pada poster membuka '+(demo?'halaman demo.':'e-kad majlis anda.')+' Teks panjang diringkaskan pada poster; jemputan penuh kekal dalam e-kad.</p>')}catch(err){open('<h2>Poster belum dapat disediakan.</h2><p class="error">'+esc(err.message)+'</p><button class="btn primary" onclick="'+(fromRSVP?'guestRSVPPoster()':'openIGPoster('+demo+')')+'">Cuba semula</button>')}finally{posterBusy=false}}
function downloadIGPoster(){if(posterBlob)saveFile(posterBlob,'sejenak-jemputan-1080x1920.png')}
async function shareIGPoster(){if(!posterBlob)return;const file=new File([posterBlob],'sejenak-jemputan-1080x1920.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Jemputan '+event.name});return}catch(err){if(err.name==='AbortError')return}}downloadIGPoster();toast('Poster dimuat turun. Pilih gambar ini untuk IG Story.')}

function money(sen){return new Intl.NumberFormat('ms-MY',{style:'currency',currency:'MYR',minimumFractionDigits:2}).format(sen/100)}
function askRemoveGift(id){open('<h2>Buang makluman Duit Salam?</h2><p>Jumlah makluman tetamu akan dikira semula. Tindakan ini tidak membatalkan atau mengubah pindahan bank.</p><button class="btn primary" onclick="removeGift(\''+id+'\')">Padam rekod</button> <button class="btn" onclick="giftLedger()">Batal</button>')}
async function removeGift(id){try{await api('/api/events/'+event.id+'/gifts/'+id,{method:'DELETE'});event=await api('/api/events/'+event.id);if(active==='dashboard')dashboard();giftLedger();toast('Rekod dipadam.')}catch(err){toast(err.message)}}

function openDuitSalam(){if(!hasFeature(event,'salam')){toast('Duit Salam tidak tersedia untuk majlis ini.');return}const demo=isDemo||invitationDemo;if(!salamAvailable()&&!demo){toast('QR Duit Salam belum tersedia.');return}open('<span class="eyebrow">TANDA INGATAN BUAT '+esc(event.name)+'</span><h2 style="margin-top:14px">Duit salam, seikhlas hati.</h2><p>Isi nama dan jumlah yang ingin diberikan. Selepas itu, QR DuitNow akan dipaparkan.</p><form id="guestsalamform"><label class="fieldlabel" for="gsname">Nama anda</label><input class="field" id="gsname" required maxlength="80" value="'+esc(guestName)+'" placeholder="Nama pemberi"><label class="fieldlabel" for="gsamount" style="margin-top:18px">Jumlah Duit Salam (RM)</label><input class="field" id="gsamount" type="number" inputmode="decimal" min="0.01" max="5000" step="0.01" placeholder="Contoh: 50.00" required><p class="formhelp">Nama dan jumlah dikongsi dengan bakal pengantin sebagai makluman tetamu, bukan bukti bayaran. Hantar semula dari peranti ini untuk mengemas kini jumlah yang sama.</p><div class="error" id="gserror" role="alert"></div><button class="btn primary" style="width:100%" type="submit">Teruskan & buka QR DuitNow ↗</button></form>');$('#guestsalamform').onsubmit=submitGuestSalam}
async function submitGuestSalam(e){e.preventDefault();const name=$('#gsname').value.trim(),raw=$('#gsamount').value;if(!name){$('#gserror').textContent='Isi nama anda dahulu.';return}if(!/^\d+(\.\d{1,2})?$/.test(raw)){$('#gserror').textContent='Masukkan jumlah dengan maksimum dua perpuluhan.';return}const [rm,sen='']=raw.split('.'),amountSen=Number(rm)*100+Number(sen.padEnd(2,'0'));if(!Number.isSafeInteger(amountSen)||amountSen<1||amountSen>500000){$('#gserror').textContent='Jumlah mestilah antara RM0.01 dan RM5,000.';return}const demo=isDemo||invitationDemo;if(demo){showGuestSalamQR({name,amountSen,demo:true});return}const button=e.submitter;button.disabled=true;button.textContent='Menyimpan makluman…';try{const key='sejenak-salam-access-'+event.id;let requestId=preferences.get(key);if(!requestId){requestId=crypto.randomUUID();preferences.set(key,requestId)}const result=await api('/api/salam/'+event.id,{method:'POST',body:JSON.stringify({requestId,name,amountSen})});guestName=name;preferences.set('sejenak-name',name);showGuestSalamQR({name,amountSen,qrUrl:result.qrUrl,demo:false})}catch(err){$('#gserror').textContent=err.message}finally{button.disabled=false;button.textContent='Teruskan & buka QR DuitNow ↗'}}
function showGuestSalamQR({name,amountSen,qrUrl,demo}){open('<span class="eyebrow">'+(demo?'DEMO DUIT SALAM':'MAKLUMAN BERJAYA DISIMPAN')+'</span><h2 style="margin-top:14px">'+money(amountSen)+'</h2><p>'+esc(name)+', terima kasih atas tanda ingatan anda.</p>'+(demo?'<div class="notice">Dalam majlis sebenar, QR bank bakal pengantin muncul di sini. Demo ini tidak merekodkan jumlah dan tidak memaparkan QR bank sebenar.</div>':'<div class="salam-payment-card"><img src="'+esc(qrUrl)+'" alt="QR DuitNow bakal pengantin"><span class="eyebrow">NAMA PENERIMA</span><h3>'+esc(event.paymentRecipient||'Semak dalam aplikasi bank')+'</h3></div><a class="btn primary" style="width:100%" href="'+esc(qrUrl)+'&download=1" download>Simpan QR DuitNow ↓</a><p class="formhelp">Makluman jumlah telah masuk ke dashboard bakal pengantin. Ini belum mengesahkan pindahan bank. Simpan QR, buka aplikasi bank dan masukkan '+money(amountSen)+' sebelum semak penerima serta sahkan pindahan.</p>')+'<button class="btn" style="width:100%;margin-top:12px" onclick="openDuitSalam()">Ubah nama / jumlah</button>')}
function reportedGiftTotal(list){return list.filter(g=>g.source==='guest-declared').reduce((n,g)=>n+g.amountSen,0)}
function giftLedgerMarkup(){const list=event.gifts||[],guest=list.filter(g=>g.source==='guest-declared'),legacy=list.filter(g=>g.source!=='guest-declared');return '<h2 style="margin:12px 0">'+money(reportedGiftTotal(list))+'</h2><p>'+guest.length+' makluman tetamu · belum disahkan oleh bank.</p><div class="notice">Jumlah dikira secara automatik daripada maklumat yang tetamu isi sebelum membuka QR. Ia bukan jumlah pindahan yang disahkan. Pengantin tidak perlu key-in jumlah.</div><div class="gift-records">'+(guest.length?guest.map(g=>'<div class="gift-record"><div><strong>'+esc(g.name)+'</strong><small>'+date(g.receivedDate)+' · Dimaklumkan tetamu</small></div><span>'+money(g.amountSen)+'</span><button type="button" aria-label="Buang makluman '+esc(g.name)+'" onclick="askRemoveGift(\''+g.id+'\')">×</button></div>').join(''):'<p class="formhelp">Belum ada jumlah dimaklumkan oleh tetamu.</p>')+'</div>'+(legacy.length?'<details class="legacy-gifts"><summary>Rekod manual terdahulu ('+legacy.length+')</summary><p class="formhelp">Rekod lama disimpan dan tidak dicampur dalam jumlah makluman tetamu.</p>'+legacy.map(g=>'<div class="gift-record"><div><strong>'+esc(g.name)+'</strong><small>'+date(g.receivedDate)+' · Rekod lama</small></div><span>'+money(g.amountSen)+'</span><button type="button" aria-label="Padam rekod lama" onclick="askRemoveGift(\''+g.id+'\')">×</button></div>').join('')+'</details>':'')}
function giftLedger(){open('<span class="eyebrow">DUIT SALAM · '+esc(event.name)+'</span><div id="salamledgerlist">'+giftLedgerMarkup()+'</div><p class="formhelp">Dashboard dikemas kini automatik setiap 15 saat ketika dibuka.</p><button class="btn" style="width:100%;margin-top:16px" onclick="modal.close();navigate(\'salam\')">Urus QR DuitNow ↗</button>');refreshGiftTotals()}
let giftPollingTimer;
async function refreshGiftTotals(){if(!event||!user)return;const id=event.id;try{const data=await api('/api/events/'+id+'/gifts');if(event?.id!==id)return;event.gifts=data;const total=$('#salamtotal');if(total)total.textContent=money(reportedGiftTotal(data));const ledger=$('#salamledgerlist');if(ledger)ledger.innerHTML=giftLedgerMarkup();const status=$('#salamautostatus');if(status)status.textContent='Dimaklumkan tetamu · auto ↗'}catch{const status=$('#salamautostatus');if(status)status.textContent='Kemas kini tertangguh · cuba semula'}}
function startGiftPolling(){if(typeof setInterval==='undefined')return;clearInterval(giftPollingTimer);giftPollingTimer=setInterval(()=>{if(active==='dashboard'&&!document.hidden)refreshGiftTotals()},15000)}


function setDemoPackage(plan){if(!ownerDemo||!event||!weddingPackages.some(p=>p.id===plan))return;event.plan=plan;const stored=ownerDemoStore.events.find(e=>e.id===event.id);if(stored)stored.plan=plan;events=events.map(e=>e.id===event.id?{...e,plan}:e);renderOwner()}
function ownerDemoBanner(){return '<div class="owner-demo-banner"><div class="demo-caption"><strong>Demo Basic <span>· Sejenak</span></strong><span>Foto, ucapan, RSVP dan jumlah ialah data contoh. Perubahan hanya untuk sesi ini.</span></div><div class="demo-preview-actions"><label class="demo-plan-picker" for="demo-package">Cuba pakej <select id="demo-package" onchange="setDemoPackage(this.value)">'+weddingPackages.map(p=>'<option value="'+p.id+'" '+(event?.plan===p.id?'selected':'')+'>'+p.name+' · RM'+p.price+'</option>').join('')+'</select></label><span class="studio-approved">'+ico('sparkles')+' Gaya pilihan · Burgundy</span><button class="btn small" onclick="resetOwnerDemo()">↻ Reset data</button><a class="btn small" href="/dashboard">Dashboard sebenar ↗</a></div></div>'}
function ownerDesign(){return 'editorial'}
function coupleMonogram(){const parts=(event?.name||user?.name||'Sejenak').split(/\s*[&+]\s*|\s+dan\s+/i).filter(Boolean);return parts.slice(0,2).map(s=>s.trim()[0]?.toUpperCase()||'').join('')||'S'}
function makeOwnerDemoStore(){const id='d0000000-0000-4000-8000-000000000001',created='2026-10-20T10:00:00Z',names=['Azmi Idris','Mak Ngah','Mat Rafiq','Aina','Hakim','Nadia'],urls=[photoURL,cover2,'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&w=900','https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=900'],posts=names.map((name,n)=>({id:'d1000000-0000-4000-8000-'+String(n+1).padStart(12,'0'),type:'photo',name,caption:['Basic indah untuk dikenang.','Meriah sungguh majlis hari ini!','Bersama keluarga tersayang.'][n%3],src:urls[n%urls.length],approved:n!==5,created,sizeBytes:420000+n*12000}));
const wishes=['Semoga bahagia hingga ke syurga. Selamat pengantin baru, Reez & Mayra! ♡','Terima kasih menjemput kami meraikan hari bahagia. Semoga rumah tangga sentiasa dirahmati.','Cantik sangat majlis! Semoga cinta ini kekal selamanya.','Moga dipermudahkan segala urusan dan murah rezeki bersama.'];wishes.forEach((text,n)=>posts.push({id:'d2000000-0000-4000-8000-'+String(n+1).padStart(12,'0'),type:'wish',name:['Azam','Mama & Papa','Farah','Pak Long'][n],text,approved:n!==3,created}));
const gifts=['Encik Ahmad','Kak Lina','Pak Long'].map((name,n)=>({id:'d3000000-0000-4000-8000-'+String(n+1).padStart(12,'0'),name,amountSen:[10000,25000,15000][n],source:'guest-declared',status:'unverified',receivedDate:'2026-10-20',created}));
const rsvps=[['Ahmad & keluarga','yes',2,2],['Mak Ngah','yes',3,1],['Farah','yes',2,0],['Hakim','maybe',0,0],['Nadia','no',0,0]].map(([name,status,adults,children],n)=>({id:'rsvp-demo-'+n,name,status,adults,children,note:'',updated:created}));
return {events:[{id,name:'Reez & Mayra',date:'2027-02-22',eventTime:'11.00 pagi – 4.00 petang',venue:'Taman Cinta, Kuala Lumpur',plan:'cerita-kita',theme:'sage',collecting:true,moderation:true,created,posts,gifts,invitation:{hosts:'Dengan ingatan tulus ikhlas daripada keluarga',title:'Walimatulurus',address:'Kuala Lumpur, Malaysia',open:true},rsvps}]}}
function resetOwnerDemo(showToast=true){if(showToast&&!confirmInvitationNavigation(()=>resetOwnerDemo(true)))return;preferences.remove('sejenak-shared-d0000000-0000-4000-8000-000000000001');preferences.remove('sejenak-guide-review-d0000000-0000-4000-8000-000000000001');ownerDemoStore=makeOwnerDemoStore();user={id:'demo-owner',name:'Reez & Mayra · Demo'};events=JSON.parse(JSON.stringify(ownerDemoStore.events));event=events[0];active='dashboard';search='';ownerFilter='all';if(modal.open)modal.close();renderOwner();if(showToast)toast('Data contoh telah dipulihkan.')}
async function ownerDemoAPI(path,opts={}){if(!ownerDemoStore)ownerDemoStore=makeOwnerDemoStore();const clone=x=>JSON.parse(JSON.stringify(x)),method=opts.method||'GET',p=path.split('/').filter(Boolean);if(path==='/api/me')return {user:{id:'demo-owner',name:'Reez & Mayra · Demo'}};
if(p[1]!=='events')throw new Error('Tindakan ini tidak tersedia dalam demo. Tiada data sebenar diubah.');
if(p.length===2){if(method==='GET')return clone(ownerDemoStore.events);if(method==='POST'){if(ownerDemoStore.events.length>=3)throw new Error('Demo membenarkan sehingga 3 galeri. Reset untuk mula semula.');const data=JSON.parse(opts.body);if(!data.name?.trim()||!data.date)throw new Error('Isi nama dan tarikh majlis.');const fresh={...data,id:data.requestId||crypto.randomUUID(),plan:'cerita-kita',collecting:true,posts:[],gifts:[],rsvps:[],created:new Date().toISOString()};ownerDemoStore.events.unshift(fresh);return clone(fresh)}}
const e=ownerDemoStore.events.find(x=>x.id===p[2]);if(!e)throw new Error('Galeri demo tidak dijumpai. Reset demo untuk memulihkannya.');
if(p.length===3){if(method==='GET')return clone(e);if(method==='PATCH'){const data=JSON.parse(opts.body);if(!hasPremium(e)&&['primaryColor','accentColor','backgroundColor','font','invitation'].some(k=>data[k]!==undefined))throw new Error('Cuba galeri contoh Reez & Mayra untuk semua ciri pakej.');if(data.invitation?.template&&!findInvitationTemplate(data.invitation.template))throw new Error('Reka bentuk E-Kad tidak sah.');Object.assign(e,data);return clone(e)}if(method==='DELETE'){ownerDemoStore.events=ownerDemoStore.events.filter(x=>x.id!==e.id);return {ok:true}}}
if(p[3]==='posts'){const post=e.posts.find(x=>x.id===p[4]);if(!post)throw new Error('Kenangan demo tidak dijumpai.');if(method==='PATCH'){Object.assign(post,JSON.parse(opts.body));return {ok:true}}if(method==='DELETE'){e.posts=e.posts.filter(x=>x.id!==post.id);return {ok:true}}}
if(p[3]==='rsvps'&&method==='GET'){if(!hasFeature(e,p[4]==='export'?'csv':'invitation'))throw new Error('Ciri ini tidak termasuk dalam pakej ini.');return clone(e.rsvps||[])}
if(p[3]==='gifts'){if(method==='GET')return clone(e.gifts);if(method==='DELETE'){e.gifts=e.gifts.filter(x=>x.id!==p[4]);return {ok:true}}}
throw new Error('Upload fail bank dan cover tidak disimpan dalam demo. Cuba edit teks, tema, atau semak foto dan ucapan contoh.');
}



const studioNavigation=[['dashboard','grid','Utama'],['events','heart','Majlis saya'],['gallery','camera','Galeri'],['share','link','Kongsi'],['invitation','book','E-Kad & RSVP'],['salam','gift','Duit Salam'],['settings','settings','Reka bentuk galeri'],['plan','grid','Pakej & storan']];
function studioNavItems(){return ['dashboard','gallery','invitation','share'].map(id=>studioNavigation.find(item=>item[0]===id)).map(([id,icon,label])=>'<button class="studio-nav-item '+(active===id?'is-active':'')+'" '+(active===id?'aria-current="page"':'')+' onclick="navigate(\''+id+'\')">'+ico(icon)+'<span>'+label+'</span>'+(active===id?'<span class="studio-nav-dot" aria-hidden="true"></span>':'')+'</button>').join('')+'<button class="studio-nav-item" onclick="openStudioMenu()">'+ico('settings')+'<span>Menu</span></button>'}
function editorialShell(body){body=storageExpiryNotice()+body;captureStudioDockMotion();modal.classList?.add('editorial-dialog');const label=studioNavigation.find(n=>n[0]===active)?.[2]||'Utama';root.innerHTML='<div class="editorial-ui">'+(ownerDemo?ownerDemoBanner():'')+'<div class="studio-layout"><aside class="studio-sidebar">'+sejenakLogo('studio-logo')+'<span class="studio-workspace-label">RUANG SEJENAK</span><div class="studio-couple"><span class="studio-monogram">'+esc(coupleMonogram())+'</span><div><strong>'+esc(event?.name||'Galeri anda')+'</strong><small>Ruang bakal pengantin</small></div></div><nav aria-label="Navigasi studio">'+studioNavItems()+'</nav><div class="studio-side-foot"><span class="studio-status-dot"></span><span>Ruang untuk kisah anda.</span><a href="'+(ownerDemo?'/dashboard':signoutPath())+'">'+(ownerDemo?'Dashboard sebenar ↗':'Log keluar ↗')+'</a></div></aside><main class="studio-main"><header class="studio-topbar"><div class="studio-breadcrumb">Sejenak <span>/</span> <strong>'+label+'</strong></div><div class="studio-top-actions"><a href="'+(event?link(event):'/demo')+'" class="studio-guest-link" target="_blank" rel="noopener">'+ico('link')+' '+(!event||ownerDemo?'Demo Basic ↗':'Lihat galeri ↗')+'</a><button class="studio-mobile-menu" onclick="openStudioMenu()" aria-label="Buka semua menu">'+ico('grid')+' Menu</button><span class="studio-avatar" aria-label="'+(ownerDemo?'Akaun demo':'Akaun bakal pengantin')+'">'+esc(coupleMonogram())+'</span></div></header><div class="studio-content">'+body+'</div><footer class="studio-footer"><span>Simpan kenangan majlis anda.</span>'+sejenakLogo('studio-footer-logo')+'</footer></main></div><nav class="studio-dock" aria-label="Navigasi Sejenak"><span class="studio-dock-indicator" aria-hidden="true" style="transform:translateX('+(studioDockIndex(active)*100)+'%)"></span>'+[['dashboard','grid','Utama'],['gallery','camera','Galeri'],['invitation','book','E-Kad'],['share','share','Kongsi']].map(([id,icon,label])=>'<button class="'+(active===id?'active':'')+'" '+(active===id?'aria-current="page"':'')+' onclick="navigate(\''+id+'\')">'+ico(icon)+'<span>'+label+'</span></button>').join('')+'<button class="'+(studioDockIndex(active)===4?'active':'')+'" onclick="openStudioMenu()">'+ico('settings')+'<span>Menu</span></button></nav></div>';syncStudioDock()}
function openStudioMenu(){captureStudioDockMotion();syncStudioDock(4);const items=studioNavigation.filter(([id])=>['events','settings','salam','plan'].includes(id)&&(!['settings','salam'].includes(id)||event));open('<span class="eyebrow">MENU SEJENAK</span><h2>Urus majlis & akaun.</h2><nav class="studio-modal-nav" aria-label="Urus majlis">'+items.map(([id,icon,label])=>'<button class="btn" onclick="modal.close();navigate(\''+id+'\')">'+ico(icon)+label+'</button>').join('')+'<a class="btn" href="/support">'+ico('heart')+' Hubungi sokongan</a></nav><div class="simple-account"><span class="eyebrow">AKAUN ANDA</span><p>'+esc(user?.name||'Akaun demo')+'</p><a class="btn" target="_top" href="'+(ownerDemo?'/login':signoutPath())+'">'+(ownerDemo?'Log masuk':'Log keluar')+' ↗</a></div>')}
function editorialDashboard(){
 if(!event){editorialShell(onboardingGuide()+'<section class="simple-no-event"><h3>Satu majlis, satu ruang.</h3><p>Selepas pembayaran disahkan, galeri majlis anda akan muncul di sini. E-Kad dan RSVP termasuk dalam Pro dan Max.</p><a href="/support">Perlukan bantuan memilih? ↗</a></section>');return}
 const posts=event.posts||[],photos=posts.filter(p=>p.type==='photo'),wishes=posts.filter(p=>p.type==='wish'),pending=posts.filter(p=>!p.approved);
 const metrics=[[photos.length,'Foto','Dalam galeri','camera',"ownerFilter='photo';navigate('gallery')"],[wishes.length,'Ucapan','Daripada tetamu','pen',"ownerFilter='wish';navigate('gallery')"],[pending.length,'Perlu semakan',pending.length?'Menunggu kelulusan':'Semua sudah disemak','book',"ownerFilter='pending';navigate('gallery')"]];
 if(hasFeature(event,'salam')||event.gifts?.length)metrics.push([money(reportedGiftTotal(event.gifts||[])),'Duit Salam','Dimaklumkan tetamu · belum disahkan','gift','dashboardSalam()']);
 const latest=(pending.length?pending:posts).slice(0,3),invitationReady=hasFeature(event,'invitation')&&!!event.invitation?.template;
 editorialShell(onboardingGuide()+'<section class="simple-event-summary" aria-label="Majlis anda"><div><span class="eyebrow">MAJLIS ANDA · '+esc(packageName(event))+'</span><h1>'+esc(event.name)+'</h1><p>'+date(event.date)+(event.venue?' · '+esc(event.venue):'')+'</p><span class="simple-collection-status">'+(event.collecting?'● Tetamu boleh menghantar kenangan':'○ Kutipan ditutup')+'</span></div><div class="simple-event-actions"><button class="btn small" onclick="navigate(\'settings\')">Edit galeri</button><button class="btn small" onclick="gallerySettings(\''+event.id+'\')">'+ico('settings')+' Tetapan</button>'+(events.length>1?'<button class="btn small" onclick="navigate(\'events\')">Tukar majlis ('+events.length+')</button>':'')+'</div></section><section class="studio-stat-grid simple-stats" aria-label="Ringkasan majlis">'+metrics.map(([value,label,note,icon,action])=>'<button class="studio-stat" onclick="'+action+'"><span class="studio-stat-top">'+label+ico(icon)+'</span><strong'+(label==='Duit Salam'?' id="salamtotal"':'')+'>'+value+'</strong><span class="studio-stat-note"'+(label==='Duit Salam'?' id="salamautostatus"':'')+'>'+note+'</span></button>').join('')+'</section><div class="simple-dashboard-grid"><section class="panel simple-invitation"><span class="eyebrow">E-KAD & RSVP</span><h2>Jemput tetamu.</h2><p>'+(hasFeature(event,'invitation')?(invitationReady?'E-Kad anda tersedia. Semak reka bentuk dan jawapan kehadiran di satu tempat.':'Pilih reka bentuk, semak butiran majlis dan simpan E-Kad anda.'):'E-Kad dan jawapan kehadiran tersedia dalam Pro dan Max.')+'</p>'+(hasFeature(event,'invitation')?'<button class="btn" onclick="createInvitation()">'+(invitationReady?'Urus E-Kad & RSVP':'＋ Cipta E-Kad')+'</button>':lockedFeatureButton('invitation'))+'</section><section class="panel simple-recent"><span class="eyebrow">'+(pending.length?'PERLU PERHATIAN':'KENANGAN TERKINI')+'</span><h2>'+(pending.length?'Semak sebelum dipaparkan.':'Dari tetamu anda.')+'</h2><div class="studio-review-list">'+(latest.length?latest.map(p=>'<button class="studio-review-item" onclick="ownerFilter=\''+(pending.length?'pending':'all')+'\';navigate(\'gallery\')">'+(p.type==='photo'?'<img src="'+media(p)+'" alt="" loading="lazy">':'<span class="studio-wish-mark">'+ico('pen')+'</span>')+'<span><strong>'+esc(p.name)+'</strong><small>'+(p.type==='photo'?'Foto':'Ucapan')+' · '+(p.approved?'Dipaparkan':'Menunggu kelulusan')+'</small></span><span aria-hidden="true">↗</span></button>').join(''):'<p>Belum ada foto atau ucapan. Kongsi pautan galeri untuk menerima kenangan pertama.</p>')+'</div></section></div>');startGiftPolling();
}

const invitationTemplateOptions=[{"id":"ivory","name":"Ivory Royale","description":"Bunga timbul & gerbang ukiran · ivory emas","style":"Emboss Emas","ink":"#725c32","paper":"#fcf6e8","accent":"#ab8d51","font":"elegant","swatches":["#f4ebd7","#b69b62","#fffaf0"],"image":"/assets/ecard-ivory.webp"},{"id":"pearl","name":"Sutra Pearl","description":"Lipatan kertas beralun · pearl & champagne","style":"Sutera","ink":"#78623c","paper":"#fffaf1","accent":"#b8a075","font":"elegant","swatches":["#fffaf1","#e1d6c0","#b8a075"],"image":"/assets/ecard-pearl.webp"},{"id":"garden","name":"Sage Herbarium","description":"Botanikal lembut · sage & ivory","style":"Garden","ink":"#38543f","paper":"#f6f5e9","accent":"#849c73","font":"elegant","swatches":["#8f9e83","#f6f5e9","#3c5942"],"image":"/assets/ecard-garden.webp"},{"id":"rosewater","name":"Rosewater Romance","description":"Cat air romantik · blush & champagne","style":"Romantik","ink":"#794655","paper":"#fff3f2","accent":"#bd8493","font":"elegant","swatches":["#ce9da5","#fff3f2","#aa797b"],"image":"/assets/ecard-rosewater.webp"},{"id":"azure","name":"Porcelain Blue","description":"Ilustrasi porselin · biru & putih","style":"Porselin","ink":"#2d507c","paper":"#f7fbff","accent":"#83a5d1","font":"classic","swatches":["#416a9e","#bdd4ec","#f7fbff"],"image":"/assets/ecard-azure.webp"},{"id":"songket","name":"Songket Emerald","description":"Geometri songket · emerald & emas","style":"Warisan","ink":"#245247","paper":"#fff7e3","accent":"#ab8945","font":"classic","swatches":["#144c40","#ab8945","#fff7e3"],"image":"/assets/ecard-songket.webp"}];
const legacyInvitationTemplates=[{id:'botanical',name:'Botanical Ivory',description:'Bunga putih, daun sage & ivory.',image:'/assets/ecard-botanical.webp'},{id:'minimal',name:'Sage Atelier',description:'Sutera sage & susunan minimal.',image:'/assets/ecard-minimal.webp'},{id:'classic',name:'Klasik Gold',description:'Bingkai emas & ukiran botanikal.',image:'/assets/ecard-classic.webp'}].concat([{"id":"midnight","name":"Midnight Celestial","description":"Art deco langit malam · navy & gold","style":"Art Deco","ink":"#fbefd3","paper":"#112338","accent":"#d1b77c","font":"classic","swatches":["#112338","#d1b77c","#fbefd3"],"image":"/assets/ecard-midnight.webp"},{"id":"terracotta","name":"Terracotta Modern","description":"Arca kertas moden · terra & sand","style":"Moden","ink":"#7e3f2a","paper":"#fff1e1","accent":"#ba7452","font":"modern","swatches":["#bd7857","#edc6a3","#fff1e1"],"image":"/assets/ecard-terracotta.webp"}]);

const bismillahText='بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ';
function bismillahHTML(className=''){return '<span class="ecard-bismillah '+className+'" lang="ar" dir="rtl">'+bismillahText+'</span>'}
function findInvitationTemplate(id){return [...invitationTemplateOptions,...legacyInvitationTemplates].find(t=>t.id===id)}
function invitationArtwork(template){return (findInvitationTemplate(template)||invitationTemplateOptions[0]).image}
function ecardDesign(e,template=e.invitation?.template){const d=defaults(e),t=findInvitationTemplate(template);return t?.ink?{...d,primaryColor:t.ink,backgroundColor:t.paper,accentColor:t.accent,font:t.font}:d}
function ecardStyle(template){const t=findInvitationTemplate(template);return t?.ink?'--ecard-ink:'+t.ink+';--ecard-paper:'+t.paper+';--ecard-accent:'+t.accent+';--green:'+t.ink+';--dark:'+t.ink+';--muted:'+t.accent+';--paper:'+t.paper+';--on-primary:'+readableInk(t.ink)+';':''}
function demoInvitationTemplate(){const id=(location.search||'').match(/(?:^|[?&])template=([a-z-]+)(?:&|$)/)?.[1];return findInvitationTemplate(id)?id:'garden'}
function invitationTemplatePreview(template,details=event){const d=ecardDesign(details,template);return '<div class="template-preview template-preview-art template-preview-'+template+'" style="'+ecardStyle(template)+'" role="img" aria-label="Preview E-Kad '+esc(details.name)+'"><img class="template-preview-artwork" src="'+invitationArtwork(template)+'" alt=""><div class="template-preview-copy">'+bismillahHTML('preview-bismillah')+'<span class="template-preview-kicker">'+esc(inviteDefaults(details).title||'Walimatulurus')+'</span><span class="template-preview-name" style="'+fontStyle(d.font)+';font-size:'+(details.name.length>55?23:details.name.length>35?28:details.name.length>22?33:40)+'px">'+esc(details.name)+'</span><span class="template-preview-date">'+date(details.date)+'</span><span class="template-preview-venue">'+esc(details.venue)+'</span><span class="template-preview-brand">'+sejenakWordmark()+'</span></div></div>'}
function invitationTemplateCards(selected=event.invitation?.template||''){const t=findInvitationTemplate(selected);return '<fieldset class="invitation-template-picker six-template-picker"><legend><span class="eyebrow">01 · PILIH REKA BENTUK E-KAD</span></legend><div class="template-picker-heading"><div><h3>Enam gaya. Satu kisah anda.</h3><p class="formhelp">Pilih warna dan gaya yang terasa seperti anda. Nama, tarikh dan lokasi dimasukkan selepas dipilih.</p></div><span class="template-collection-count">6 reka bentuk</span></div><input id="itemplate" type="hidden" value="'+(t?.id||'')+'"><div class="template-carousel-toolbar"><span>Swipe untuk lihat pilihan</span><div><button class="template-carousel-arrow" type="button" aria-label="Pilihan E-Kad sebelumnya" onclick="scrollInvitationTemplates(-1)">‹</button><button class="template-carousel-arrow" type="button" aria-label="Pilihan E-Kad seterusnya" onclick="scrollInvitationTemplates(1)">›</button></div></div><div class="invitation-template-options six-template-options" role="group" aria-label="Enam pilihan reka bentuk E-Kad" tabindex="0" onkeydown="invitationTemplateKey(event)">'+invitationTemplateOptions.map((o,n)=>'<button type="button" data-template="'+o.id+'" class="template-option '+(o.id===t?.id?'selected':'')+'" aria-pressed="'+(o.id===t?.id)+'" onclick="selectInvitationTemplate(\''+o.id+'\')"><span class="template-art-frame"><img class="template-thumb template-art-thumb" src="'+o.image+'" alt="Artwork '+o.name+' tanpa nama atau tarikh" loading="lazy" width="1086" height="1448"><span class="template-bismillah-layer" style="color:'+o.ink+'">'+bismillahHTML('thumb-bismillah')+'</span><span class="template-style-badge">'+o.style+'</span><span class="template-selected-mark" aria-hidden="true">'+(o.id===t?.id?'✓':'')+'</span></span><span class="template-option-name"><span>'+o.name+'</span><small>'+String(n+1).padStart(2,'0')+'</small></span><span class="template-option-description">'+o.description+'</span><span class="template-swatches" aria-hidden="true">'+o.swatches.map(c=>'<i style="background:'+c+'"></i>').join('')+'</span></button>').join('')+'</div><p class="template-selection-status" id="template-selection-status" role="status" aria-live="polite">'+(t?'Dipilih: '+t.name:'Belum pilih reka bentuk')+'</p><div id="template-live-preview">'+(t?invitationTemplatePreview(t.id):'<div class="template-empty-preview">'+ico('sparkles')+'<strong>Preview peribadi anda muncul di sini.</strong><p>Pilih satu daripada enam reka bentuk di atas.</p></div>')+'</div><p class="formhelp">Semak preview dan butiran majlis, kemudian tekan Jana E-Kad. Pilihan lama yang sudah disimpan masih boleh digunakan.</p></fieldset>'}
function updateInvitationDraftPreview(){invitationDirty=true;const template=$('#itemplate')?.value;if(!findInvitationTemplate(template))return;const details={...event,name:$('#iname')?.value.trim()||event.name,date:$('#idate')?.value||event.date,venue:$('#ivenue')?.value||event.venue,invitation:{...event.invitation,title:$('#ititle')?.value||inviteDefaults(event).title}};$('#template-live-preview').innerHTML=invitationTemplatePreview(template,details)}
function selectInvitationTemplate(id){const t=invitationTemplateOptions.find(o=>o.id===id);if(!t)return;$('#itemplate').value=id;for(const b of document.querySelectorAll?.('[data-template]')||[]){const selected=b.dataset.template===id;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));const mark=b.querySelector?.('.template-selected-mark');if(mark)mark.textContent=selected?'✓':''}$('#template-selection-status').textContent='Dipilih: '+t.name;updateInvitationDraftPreview()}
function scrollInvitationTemplates(direction){const list=$('.six-template-options');if(!list)return;list.scrollBy?.({left:direction*Math.max(220,list.clientWidth*.8),behavior:guestReducedMotion()?'auto':'smooth'})}
function invitationTemplateKey(e){if(e.target!==e.currentTarget)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();scrollInvitationTemplates(e.key==='ArrowRight'?1:-1)}}

function showGeneratedInvitation(){open('<span class="eyebrow">E-KAD ANDA SUDAH DIJANA</span><h2 style="margin-top:14px">Sedia untuk menjemput mereka.</h2>'+invitationTemplatePreview(inviteDefaults(event).template)+'<div class="package-modal-actions"><a class="btn primary" href="'+inviteLink(event)+'" target="_blank" rel="noopener">Buka E-Kad ↗</a><button class="btn" onclick="openIGPoster(false)">Jana poster IG 9:16 ↓</button></div><p class="formhelp">'+(ownerDemo?'Demo ini menggunakan data contoh. Perubahan hanya untuk sesi ini.':'Kongsi pautan E-Kad anda untuk jemputan dan RSVP tetamu.')+'</p>')}


function sejenakWordmark(){return '<span class="sejenak-wordmark"><span class="sejenak-logo-word">sejenak</span><svg class="sejenak-logo-mark" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 2v20M2 12h20M4.9 4.9l14.2 14.2M4.9 19.1 19.1 4.9" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/></svg></span>'}
function sejenakLogo(className=''){return '<a class="sejenak-logo '+className+'" href="/" aria-label="Sejenak, laman utama">'+sejenakWordmark()+'</a>'}


function studioDockIndex(section){const n=['dashboard','gallery','invitation','share'].indexOf(section);return n<0?4:n}
function syncStudioDock(index=studioDockIndex(active)){const dock=$('.studio-dock');if(!dock||typeof dock.querySelector!=='function')return;const indicator=dock.querySelector('.studio-dock-indicator');if(!indicator)return;const previous=studioDockVisualIndex,snapshot=studioDockMotionSnapshot;studioDockMotionSnapshot=null;studioDockVisualIndex=index;const target='translateX('+(index*100)+'%)';indicator.style.transform=target;const buttons=Array.from(dock.querySelectorAll('button'));buttons.forEach((button,n)=>{button.classList.toggle('active',n===index);if(n===index)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});const reduced=typeof window!=='undefined'&&window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;const from=snapshot?.index??previous,scale=snapshot?.scale??1;if(from===null||Math.abs(from-index)<.001&&Math.abs(scale-1)<.001||reduced||typeof indicator.animate!=='function')return;indicator.animate([{transform:'translateX('+(from*100)+'%) scaleX('+scale+')',filter:'brightness(1)'},{offset:.62,transform:'translateX('+((from+(index-from)*.86)*100)+'%) scaleX(1.10)',filter:'brightness(1.09)'},{transform:target+' scaleX(1)',filter:'brightness(1)'}],{duration:470,easing:'cubic-bezier(.22,.7,.2,1)'});buttons[previous]?.animate?.([{color:'#ffffff'},{color:'#7f3e50'}],{duration:210,easing:'ease-out'});buttons[index]?.animate?.([{color:'#7f3e50'},{color:'#ffffff'}],{duration:310,delay:90,fill:'backwards'})}


function captureStudioDockMotion(){studioDockMotionSnapshot=null;const indicator=$('.studio-dock-indicator');if(!indicator||!indicator.offsetWidth||typeof window==='undefined'||typeof window.getComputedStyle!=='function')return;const transform=window.getComputedStyle(indicator).transform,match=transform?.match(/^matrix\(([^)]+)\)$/);if(!match)return;const parts=match[1].split(',').map(Number);if(parts.length!==6||parts.some(n=>!Number.isFinite(n)))return;studioDockMotionSnapshot={index:parts[4]/indicator.offsetWidth,scale:Math.hypot(parts[0],parts[1])}}

async function init(){try{if(location.pathname==='/login'){await loginPage();return}if(location.pathname==='/auth/logout'){logoutPage();return}if(location.pathname==='/support'){await supportPage();return}if(location.pathname==='/checkout'||location.pathname==='/checkout/status'){await checkoutPage();return}if(['/admin','/admin-demo'].includes(location.pathname)){await Promise.resolve();await adminPage();return}if(ownerDemo){resetOwnerDemo(false);if(location.hash==='#invitation')await navigate('invitation');return}if(invitationDemo){event={...demoEvent(),plan:'cerita-kita',invitation:{hosts:'Dengan ingatan tulus ikhlas daripada keluarga',address:'Kuala Lumpur, Malaysia',template:demoInvitationTemplate()}};invitationCard();return}if(location.pathname.startsWith('/i/')){event=await api('/api/invitation/'+location.pathname.split('/')[2]);invitationCard();return}if(isDemo){event=demoEvent();guest();return}if(location.pathname.startsWith('/e/')){event=await api('/api/guest/'+location.pathname.split('/')[2]);guest();return}const [me,availability]=await Promise.all([api('/api/me'),api('/api/chip/availability').catch(()=>({live:false}))]);user=me.user;commerceAvailability=availability;if(location.pathname.startsWith('/dashboard')){if(!user){location.href='/login?return_to=%2Fdashboard';return}events=await api('/api/events');if(events.length){const selected=events.find(e=>e.id===preferences.get('sejenak-active-event'))||events[0];event=await api('/api/events/'+selected.id);rememberActiveEvent(selected.id)}renderOwner();return}landing()}catch(e){root.innerHTML='<header class="topbar">'+brand+'</header><section class="section" style="padding-top:80px"><h2>Ruang ini belum dapat dibuka.</h2><p class="error">'+esc(e.message)+'</p><button class="btn primary" onclick="location.reload()">Cuba semula</button> <a class="btn" href="/">Laman utama</a></section>'}}init();

function askDeleteEvent(){if(!event)return;const id=event.id;open('<h2>Padam Galeri Tetamu ini?</h2><p><strong>'+esc(event.name)+'</strong> akan dipadam bersama foto, ucapan, RSVP, checklist dan rekod Duit Salam. Pautan serta QR majlis tidak lagi boleh digunakan. Tindakan ini tidak boleh diundur.</p><form id="deleteeventform"><label class="fieldlabel" for="deleteconfirm">Taip PADAM untuk mengesahkan</label><input class="field" id="deleteconfirm" autocomplete="off" required pattern="PADAM"><div class="error" id="deleteeventerror" role="alert"></div><button class="btn danger" type="submit">Padam Galeri Tetamu</button> <button class="btn" type="button" onclick="modal.close()">Batal</button></form>');$('#deleteeventform').onsubmit=async e=>{e.preventDefault();if($('#deleteconfirm').value!=='PADAM')return;const button=e.submitter;button.disabled=true;try{await api('/api/events/'+id,{method:'DELETE'});events=events.filter(x=>x.id!==id);if(event?.id===id){event=null;if(events.length){try{event=await api('/api/events/'+events[0].id)}catch{toast('Galeri telah dipadam. Muat semula untuk membuka galeri lain.')}}preferences.set(ownerDemo?'sejenak-demo-active-event':'sejenak-active-event',event?.id||'')}modal.close();active='dashboard';dashboard();toast('Galeri Tetamu telah dipadam.')}catch(err){$('#deleteeventerror').textContent=err.message;button.disabled=false}}}

async function gallerySettings(id){const request=++ownerSelectionRequest;try{const selected=await api('/api/events/'+id);if(request!==ownerSelectionRequest)return;event=selected;rememberActiveEvent(id);if(active==='dashboard')dashboard();open('<span class="eyebrow">TETAPAN GALERI</span><h2>'+esc(event.name)+'</h2><p>Urus reka bentuk Galeri Tetamu, foto dan ucapan. E-Kad diedit dalam E-Kad & RSVP.</p><div style="display:flex;gap:12px;flex-wrap:wrap"><button class="btn primary" onclick="modal.close();navigate(\'settings\')">Reka bentuk galeri</button><button class="btn" onclick="modal.close();navigate(\'gallery\')">Foto &amp; ucapan</button><button class="btn danger" onclick="askDeleteEvent()">Padam galeri</button></div>')}catch(err){toast(err.message)}}

function restoreGalleryGuestName(){try{const profile=JSON.parse(preferences.get('sejenak-rsvp-profile-'+event.id)||'null');if(profile?.eventId===event.id&&typeof profile.name==='string'&&profile.name.trim()&&profile.name.length<=80)guestName=profile.name}catch{}}


// Final journey audit: preserve edits and make demo outcomes explicit.
let pendingInvitationNavigation=null;
function confirmInvitationNavigation(next){
 if(active!=='invitation'||!invitationDirty)return true;
 pendingInvitationNavigation=next;
 open('<h2>Perubahan E-Kad belum disimpan.</h2><p>Kembali ke editor dan tekan Jana E-Kad untuk menyimpan perubahan anda.</p><div class="journey-actions"><button class="btn primary" onclick="pendingInvitationNavigation=null;modal.close()">Teruskan mengedit</button><button class="btn" onclick="discardInvitationChanges()">Keluar tanpa simpan</button></div>');
 return false;
}
function discardInvitationChanges(){const next=pendingInvitationNavigation;pendingInvitationNavigation=null;invitationDirty=false;modal.close();next?.()}
if(typeof window!=='undefined'&&typeof window.addEventListener==='function')window.addEventListener('beforeunload',e=>{if(active==='invitation'&&invitationDirty){e.preventDefault();e.returnValue=''}});
function demoSubmissionReceipt(type){const label=type==='wish'?'Ucapan':'Foto';open('<span class="eyebrow">SIMULASI TETAMU</span><h2>'+label+' anda sedia dihantar.</h2><p>Dalam majlis sebenar, '+label.toLowerCase()+' akan dihantar kepada pengantin dan dipaparkan selepas diluluskan jika semakan diaktifkan.</p><p class="formhelp">Ini demo sahaja. '+label+' ini tidak dimuat naik atau disimpan.</p><div class="journey-actions"><button class="btn primary" onclick="modal.close()">Kembali ke demo tetamu</button><a class="btn" href="/#pakej">Pilih pakej untuk majlis anda ↗</a></div>')}
function ownerGalleryEmpty(){if(search||ownerFilter!=='all')return '<div class="empty"><h3>'+(ownerFilter==='pending'&&!search?'Semua sudah disemak.':'Tiada hasil untuk pilihan ini.')+'</h3><p>'+(search?'Cuba nama lain atau kosongkan carian.':'Pilih Semua untuk melihat foto dan ucapan yang lain.')+'</p><button class="btn" onclick="search=\'\';ownerFilter=\'all\';ownerGallery()">Lihat semua kenangan</button></div>';return '<div class="empty"><h3>Ruang untuk kenangan baharu.</h3><p>Kongsi pautan atau QR galeri supaya tetamu boleh menghantar foto dan ucapan.</p><button class="btn" onclick="navigate(\'share\')">Kongsi QR galeri ↗</button></div>'}
